'use strict';
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const repo=path.resolve(__dirname,'..'),rt=JSON.parse(fs.readFileSync('/private/tmp/seti-free-card-purpose-20261119.json')).runtime;
const load=name=>JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(repo,'reports/ai-foundation-20261119',name)))).envelope;
const before=load('teacher-r4-before-input287-20261119-v1.json.gz'),expected=load('teacher-r4-blind-after287-20261119-v1.json.gz'),seed='seti-free-analyze-v1',seat='player-white';
const output=path.join(repo,'reports/ai-foundation-20261119/free-card-purpose-native-execution-20261119-v1.json'),previous=fs.existsSync(output)?JSON.parse(fs.readFileSync(output)):null;
if(previous){assert.equal(previous.status,'failed');assert.equal(previous.newRealInputs,0);assert(previous.failure.message.includes('getActiveDecisionNode'));}
const {createSimulationRuleComposition}=require(path.join(rt,'randomizer/training/simulation-rule-composition')),{createSeededRandom}=require(path.join(rt,'randomizer/game/random')),{buildRuleObservation}=require(path.join(rt,'randomizer/app/rule-observation')),{createAnalysisPort}=require(path.join(rt,'randomizer/game/ai/analysis-port')),agent=require(path.join(rt,'randomizer/game/ai/search-agent')),coordinator=require(path.join(rt,'randomizer/game/ai/machine-player-coordinator'));
const kernel=createSimulationRuleComposition({seed,random:createSeededRandom(seed),activePlayerCount:4,trustedProjectionReader:true,projectCounterfactualState:(s,v)=>buildRuleObservation(s,seed,v?.playerId)}),c=kernel.composition;
const report={status:'running',runtime:rt,policy:agent.VERSION,newGames:0,newAISearches:previous?.newAISearches||0,newRealInputs:0,...(previous?{priorVerificationFailure:previous.failure}: {})};const persist=()=>fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n');persist();
try{kernel.newGame({seed});assert(c.lifecycle.restore(before).ok);assert.deepEqual(c.lifecycle.save().envelope,before);
 const port=createAnalysisPort({composition:c,seatId:seat,maxCacheEntries:0}),player=agent.createSearchAgent({seatId:seat,analysisPort:port}),boundary=coordinator.createMachinePlayerCoordinator({composition:c,execute:()=>assert.fail('read only')}).readBoundary(seat);
 let result;if(previous){const cold=JSON.parse(fs.readFileSync(path.join(repo,'reports/ai-foundation-20261119/free-card-purpose-before287-cold-20261119-v1.json')));assert.equal(cold.status,'passed');result={actionId:cold.action.actionId,search:{complete:cold.complete,diagnostics:{nativeExecutions:cold.nativeInputs},rootAndSearchMilliseconds:cold.milliseconds}};report.reusedVerifiedColdAction=true;}else{report.newAISearches++;persist();result=player.decide(boundary);}const action=boundary.legalActions.find(a=>a.actionId===result.actionId);
 assert.equal(action?.target.source,'blind');assert(result.search.complete);assert(result.search.diagnostics.nativeExecutions<=256&&result.search.rootAndSearchMilliseconds<=600);assert.deepEqual(c.lifecycle.save().envelope,before);
 const decision=boundary.sessionDecision,executed=c.inputPort.submitDecision({decisionId:decision.decisionId,decisionVersion:decision.decisionVersion,ownerId:decision.ownerId,choice:action});assert(executed.ok);report.newRealInputs++;persist();
 const actual=c.lifecycle.save().envelope;assert.deepEqual(actual,expected);Object.assign(report,{status:'verified',selectedAction:action,fullNativeStateSessionAndRngEqual:true,expectedAfter287:'teacher-r4-blind-after287-20261119-v1.json.gz',nativeStateSha256:crypto.createHash('sha256').update(actual.committedState).digest('hex'),coldNative:result.search.diagnostics.nativeExecutions,coldMilliseconds:result.search.rootAndSearchMilliseconds});persist();console.log(JSON.stringify(report));
}catch(error){report.status='failed';report.failure={message:error.message,stack:error.stack};persist();console.error(error.stack);process.exitCode=1;}finally{c.dispose();}
